UPDATE mcp_tool SET enabled=FALSE,available=FALSE
WHERE server_id=#{serverId,typeHandler=com.febridge.persistence.UuidTypeHandler}
  AND name NOT IN (SELECT jsonb_array_elements_text(CAST(#{names} AS jsonb)))

mapper.select:

JOIN agent_mcp_grant g ON g.server_id=t.server_id
WHERE g.agent_id=#{agentId,typeHandler=com.febridge.persistence.UuidTypeHandler}
ORDER BY t.name,t.id

SELECT * FROM tool_call_audit
WHERE agent_id=#{agentId,typeHandler=com.febridge.persistence.UuidTypeHandler}
  AND request_id=#{requestId,typeHandler=com.febridge.persistence.UuidTypeHandler}
ORDER BY created_at,id LIMIT 100
